def sum_subsequence_widths(nums):
    nums=sorted(nums);mod=10**9+7;answer=0;power=1
    for i,value in enumerate(nums):
        answer=(answer+(value-nums[-1-i])*power)%mod;power=power*2%mod
    return answer

